function slugify(name) {
  return name.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'producto'
}

// The id keeps this URL independent from other products being renamed or
// removed.
export function getProductSlug(product) {
  return `${slugify(product.nombre)}-${product.id_producto}`
}

// Reproduce the slugs generated by the first routing implementation so old
// bookmarks remain valid after switching to stable id-based URLs.
function getLegacyProductSlug(product, products) {
  const used = new Set()
  const sorted = [...products].sort((a, b) => Number(a.id_producto) - Number(b.id_producto))
  for (const item of sorted) {
    const base = slugify(item.nombre)
    let slug = base
    while (used.has(slug)) slug += `-${item.id_producto}`
    used.add(slug)
    if (item.id_producto === product.id_producto) return slug
  }
  return slugify(product.nombre)
}

export function findProductBySlug(products, slug) {
  return products.find((product) => getProductSlug(product) === slug)
    ?? products.find((product) => getLegacyProductSlug(product, products) === slug)
    ?? (() => {
      const idMatch = slug.match(/-(\d+)$/)
      return idMatch
        ? products.find((product) => Number(product.id_producto) === Number(idMatch[1]))
        : null
    })()
    ?? null
}
